"@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap');

:root {
  --bg-primary: #080c14;
  --bg-secondary: #0f172a;
  --bg-card: rgba(15, 23, 42, 0.65);
  --bg-card-hover: rgba(30, 41, 59, 0.8);
  --bg-input: #1e293b;
  --border-color: rgba(255, 255, 255, 0.06);
  --border-color-hover: rgba(255, 255, 255, 0.15);

  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-muted: #64748b;

  /* Accent Colors */
  --accent-primary: #8b5cf6; /* Purple */
  --accent-primary-hover: #7c3aed;
  --accent-primary-glow: rgba(139, 92, 246, 0.15);

  --accent-green: #10b981; /* Emerald Green */
  --accent-green-glow: rgba(16, 185, 129, 0.15);

  --accent-red: #ef4444; /* Rose Red */
  --accent-red-glow: rgba(239, 68, 68, 0.15);

  --accent-blue: #0284c7; /* Sky Blue */
  --accent-blue-glow: rgba(2, 132, 199, 0.15);

  --accent-gold: #f59e0b; /* Amber */
  --accent-gold-glow: rgba(245, 158, 11, 0.15);

  --font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --transition-smooth: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  --border-radius: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  min-height: 100vh;
  overflow-x: hidden;
  background-image: 
    radial-gradient(at 0% 0%, rgba(139, 92, 246, 0.08) 0px, transparent 50%),
    radial-gradient(at 100% 100%, rgba(16, 185, 129, 0.05) 0px, transparent 50%),
    radial-gradient(at 50% 50%, rgba(2, 132, 199, 0.05) 0px, transparent 50%);
  background-attachment: fixed;
}

/* Scrollbar styles */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-track {
  background: var(--bg-primary);
}
::-webkit-scrollbar-thumb {
  background: var(--bg-input);
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}\
