"  // Start mock engine that fluctuates prices every 5 seconds to simulate real-time
  private startMockEngine() {
    if (this.intervalId) return;

    this.intervalId = window.setInterval(() => {
      // Pick a random asset to fluctuate
      const symbols = Object.keys(this.marketData);
      const randomSymbol = symbols[Math.floor(Math.random() * symbols.length)];
      const asset = this.marketData[randomSymbol];

      // Mutual funds change slower than stocks
      const volatility = asset.type === 'stock' ? 0.008 : 0.002;
      const percentChange = (Math.random() - 0.49) * 2 * volatility; // slightly positive drift

      const newPrice = asset.price * (1 + percentChange);
      const roundedPrice = asset.type === 'stock' 
        ? Math.round(newPrice * 100) / 100 
        : Math.round(newPrice * 10000) / 10000;

      const change = roundedPrice - asset.prevClose;
      const changePercent = (change / asset.prevClose) * 100;

      this.marketData[randomSymbol] = {
        ...asset,
        price: roundedPrice,
        change,
        changePercent,
        lastUpdated: new Date().toLocaleTimeString()
      };

      this.notify(randomSymbol);
    }, 4000);
  }"

